''','''/**
 * Announces that a write was refused because the plan had no room for it.
 * Every create path that turns a request down on quota grounds calls this, so
 * `billing.limit_exceeded` always means "something was refused" — the owner's
 * plan-limit alert hangs off it.
 */
export async function reportLimitRefusal(
  orgId: OrgId,
  actorId: UserId | null,
  resource: LimitedResource,
  limit: number,
  used: number,
): Promise<void> {
  await emit("billing.limit_exceeded", {
    ...envelope(orgId, actorId),
    resource,
    limit,
    used,
