/**
 * Private helpers that turn stored ids into the hrefs the App Router serves.
 *
 * Alerts, digest entries and search hits all carry links; the route shapes
 * themselves live in `@/lib/url`, and this module only loads the slugs and
 * numbers those builders need.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

async function orgSlugFor(orgId: OrgId): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? orgId;
}

/** `/<org>/projects/<project>/issues/<number>`, or the org root if gone. */
export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(orgSlug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(orgSlug);

  return issuePath(orgSlug, project.slug, issue.number);
}

/** A comment has no page of its own; it lives on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) return orgPath(await orgSlugFor(orgId));
  return issueHref(orgId, comment.issueId);
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project) return orgPath(orgSlug);
  return projectPath(orgSlug, project.slug);
}

export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  return settingsPath(await orgSlugFor(orgId), section);
}

