# fan-out
start=s.index('function registerFanOut(): void {')
new='''function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  // Being assigned at creation is an assignment like any later one; the
  // actor filter in `notify` drops a creator who assigned themselves.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue you are assigned changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];
    const href = await issueHref(payload.orgId, payload.issueId);

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner hears about every new member; the person who joined is the
  // actor and is never told about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: await settingsHref(payload.orgId, "members"),
      actorId: payload.actorId ?? payload.userId,
    });
  });

  // A write was refused for lack of room on the plan. One unread alert per
  // resource is enough; once the owner has read it, the next refusal counts.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const label = LIMIT_LABELS[payload.resource];
    const title = `Your plan has no room for more ${label}`;

    const pending = await notificationRepo.hasUnreadMatching(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      title,
    );
    if (pending) return;

    await notify(
      payload.orgId,
      "plan_limit_reached",
      [org.ownerId],
      {
        title,
        body: `${org.name} uses ${payload.used} of ${payload.limit} ${label} on its plan; a request for more was refused`,
        href: await settingsHref(payload.orgId, "billing"),
        actorId: payload.actorId,
      },
      { includeActor: true },
    );
  });
}

registerFanOut();
