 * Inboxes and preferences are personal: on top of the role check, the
 * recipient must be the actor, whatever the actor's role.
 */
function assertOwnInbox(
  actor: Actor,
  action: PermissionAction,
  orgId: OrgId,
  recipientId: UserId,
): void {
  const resource = notificationResource(orgId, recipientId);
  assertCan(actor, action, resource);
  if (recipientId !== actor.userId) {
    throw new PermissionDeniedError(action, {
      action,
      resourceKind: resource.kind,
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

